// Neon Sutra: a mandala that folds space into itself. The plane is mirrored
// into petals, then repeatedly tiled, mirrored and turned; every level
// draws glowing rings, and the levels turn at different speeds, so the
// whole lattice of light keeps sliding through itself and re-locking into
// new symmetries. Rings pump outward on every beat. In the spirit of
// kishimisu's "Introduction to Shader Art Coding".

#define TAU 6.28318531
#define PI 3.14159265

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;

  // Petals: mirror the plane into wedges.
  float seg = PI / float(petals);
  float r0 = length(p);
  float a = atan(p.y, p.x) + j * 0.021;
  a = abs(mod(a, 2.0 * seg) - seg);
  vec2 q = r0 * vec2(cos(a), sin(a));
  q *= mix(0.6, 2.2, zoom) * (1.0 + 0.15 * sin(j * 0.09));
  // A slow swirl that tightens towards the centre.
  q = rot(swirl * 1.5 * sin(j * 0.05) * exp(-r0)) * q;
  vec2 q0 = q;

  float sc = mix(1.2, 2.1, fold) + 0.08 * sin(j * 0.061);
  float hue = colour + j * 0.017;
  vec3 col = vec3(0.0);
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    // Tile, mirror, re-centre, turn. Mirroring keeps every level seamless.
    q = abs(fract(q * sc) - 0.5) - 0.25;
    q = rot(j * 0.023 * (fi + 1.0) + fi * 0.9) * q;

    // Rings morph between circles, diamonds and squares.
    float form = 0.5 + 0.5 * sin(j * 0.031 + fi * 1.3);
    float d = mix(length(q), mix(abs(q.x) + abs(q.y), max(abs(q.x), abs(q.y)), form), shape);
    d *= exp(-length(q0) * 0.55);
    vec3 c = palette(length(q0) * 0.45 + fi * 0.31 + hue);
    float freq = mix(5.0, 14.0, rings);
    d = abs(sin(d * freq - j * 0.7 + fi * 1.7)) / freq;
    col += c * pow(0.011 / max(d, 2e-4), 1.25) * mix(1.0, 0.5, fold);
  }

  // Burning core, soft shoulder.
  col += palette(hue + 0.5) * 0.04 / (r0 * r0 + 0.02);
  col = 1.0 - exp(-col * 0.9);
  return clamp(col, 0.0, 1.0);
}
